[Form]
public class AVAMultiformBaseData extends FormRun
{

    InventTable                 callerInventTable;

    [FormObservable]
    ItemId          itemId;

    [FormObservable]
    InventUnitId    unitId;
    [FormObservable]
    InventSiteId    inventSiteId;


}

protected InventTable inventTable()
{
    switch(element.args().dataset())
    {
        case tableNum(InventTable):
            return element.args().record();
    }
    return null;
}

void init()
{
    super();
    if (element.args())
    {
        callerInventTable = this.inventTable();
    }

    if (!callerInventTable)
    {
        throw error(Error::missingFormActiveBuffer(formstr(AVARouteBOMInvent), tablestr(InventTable)));
    }

    if (!callerInventTable.isFormulaOrBOMAllowed())
    {
        throw error(strfmt("@PRO2616", callerInventTable.ItemId));
    }

    if (!callerInventTable.inventItemType().canHaveRoutes())
    {
        throw error(strFmt("@SYS22874", callerInventTable.ItemId));
    }

    this.inititemid();

}

private void initItemId()
{
    WHSInventFixedLocation whsInventFixedLocation;
    itemId = callerInventTable.ItemId;
    select firstonly WHSInventFixedLocation where whsInventFixedLocation.ItemId == itemId;
    inventSiteId = whsInventFixedLocation.InventSiteId;
    unitId = callerInventTable.inventUnitId();
    if (!inventSiteId)
    {
        inventSiteId = inventItemInventSetup::findDefault(itemId).inventDimDefault().InventSiteId;
    }
}

public void executeQuery()
{
    element.initItemId();
    SysQuery::findOrCreateRange(inventtable_ds.queryBuildDataSource(), fieldNum(inventtable, ItemId)).value(ItemId);
    super();

}

public void linkActive()
{
    super();
    if (element.args())
    {
        callerInventTable = element.inventTable();
    }

    this.executeQuery();
}

public int active()
{
    int ret;

    if (RouteVersion.RouteId)
    {
        SysQuery::findOrCreateRange(Route_ds.queryBuildDataSource(), fieldNum(route, RouteId)).value(RouteVersion.RouteId);
        SysQuery::findOrCreateRange(RouteOpr_ds.queryBuildDataSource(), fieldNum(RouteOpr, RouteRelation)).value(RouteVersion.RouteId);
    } 
    else
    {
        SysQuery::findOrCreateRange(Route_ds.queryBuildDataSource(), fieldNum(route, RouteId)).value(SysQuery::valueEmptyString());
    }
    ret = super();

    return ret;
}

public void init()
{
    super();

    if (!RouteVersion.RouteId)
    {
        SysQuery::findOrCreateRange(Route_ds.queryBuildDataSource(), fieldNum(route, RouteId)).value(SysQuery::valueEmptyString());
        //SysQuery::findOrCreateRange(RouteOpr_ds.queryBuildDataSource(), fieldNum(RouteOpr, RouteRelation)).value(RouteVersion.RouteId);
    }

}

public int active()
{
    int ret;

    if (BOMVersion.BOMId)
    {
        SysQuery::findOrCreateRange(BOM_ds.queryBuildDataSource(), fieldNum(BOM, BOMId)).value(bomVersion.BOMId);
    }
    else
    {
        SysQuery::findOrCreateRange(BOM_ds.queryBuildDataSource(), fieldNum(BOM, BOMId)).value(SysQuery::valueEmptyString());            
    }
    ret = super();

    return ret;
}

public void init()
{

    super();
    if (!BOMVersion.BOMId)
    {
        SysQuery::findOrCreateRange(BOM_ds.queryBuildDataSource(), fieldNum(BOM, BOMId)).value(SysQuery::valueEmptyString());
    }

}
